create or replace function app.is_staff(_user_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role in ('owner','admin','developer')); $$;
create or replace function public.create_frycord_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,username,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'username','user_'||replace(new.id::text,'-','')),coalesce(new.raw_user_meta_data->>'display_name',new.raw_user_meta_data->>'full_name','New member')) on conflict(id) do nothing; return new; end; $$;
create trigger frycord_profile_signup after insert on auth.users for each row execute function public.create_frycord_profile();
create or replace function public.join_world_chat() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.server_members(server_id,user_id,role) select id,new.id,'member' from public.servers where invite_code='worldchat' on conflict(server_id,user_id) do nothing; return new; end; $$;
create trigger frycord_join_world after insert on public.profiles for each row execute function public.join_world_chat();
create or replace function public.protect_world_chat() returns trigger language plpgsql security definer set search_path=public as $$ begin if TG_TABLE_NAME='servers' then if old.invite_code='worldchat' then raise exception 'World Chat cannot be removed or changed'; end if; elsif exists(select 1 from public.servers where id=old.server_id and invite_code='worldchat') then raise exception 'Everyone stays in World Chat'; end if; return old; end; $$;
create trigger protect_world_server before delete or update on public.servers for each row execute function public.protect_world_chat();
create trigger protect_world_members before delete on public.server_members for each row execute function public.protect_world_chat();
revoke update on public.profiles from authenticated;
grant update(username,display_name,avatar_url,bio,status,theme,language,background_url,region) on public.profiles to authenticated;
create or replace function public.claim_daily_points() returns integer language plpgsql security definer set search_path=public as $$ declare p public.profiles; today date; zone text; begin if auth.uid() is null then raise exception 'Sign in first'; end if; select * into p from public.profiles where id=auth.uid() for update; zone:=case p.region when 'americas' then 'America/Los_Angeles' when 'europe' then 'Europe/London' when 'asia' then 'Asia/Tokyo' when 'oceania' then 'Australia/Sydney' else 'UTC' end; today:=(now() at time zone zone)::date; if p.last_points_claim is not null and p.last_points_claim >= today then raise exception 'Daily points already claimed'; end if; update public.profiles set points=points+50,last_points_claim=today where id=auth.uid() returning points into p.points; return p.points; end; $$;
create or replace function public.redeem_vip() returns integer language plpgsql security definer set search_path=public as $$ declare balance integer; begin if auth.uid() is null then raise exception 'Sign in first'; end if; select points into balance from public.profiles where id=auth.uid() for update; if public.has_role(auth.uid(),'vip') then raise exception 'You already have VIP'; end if; if balance<1000 then raise exception 'VIP costs 1000 points'; end if; update public.profiles set points=points-1000 where id=auth.uid(); insert into public.user_roles(user_id,role) values(auth.uid(),'vip'); return balance-1000; end; $$;
revoke all on function public.claim_daily_points(),public.redeem_vip() from public,anon; grant execute on function public.claim_daily_points(),public.redeem_vip() to authenticated;
create or replace function public.guard_chat_message() returns trigger language plpgsql security definer set search_path=public as $$ declare consecutive integer; begin if public.is_suspended(new.author_id) then raise exception 'Your account is temporarily suspended'; end if; if new.content ~* '\m([[:alnum:]_]+)[[:space:]]+\1\M' then raise exception 'Do not repeat a word twice in a row'; end if; if TG_TABLE_NAME='messages' then perform pg_advisory_xact_lock(hashtext(new.channel_id::text)); select count(*) into consecutive from (select author_id from public.messages where channel_id=new.channel_id order by created_at desc,id desc limit 5) m where m.author_id=new.author_id; else perform pg_advisory_xact_lock(hashtext(new.thread_id::text)); select count(*) into consecutive from (select author_id from public.dm_messages where thread_id=new.thread_id order by created_at desc,id desc limit 5) m where m.author_id=new.author_id; end if; if consecutive=5 then raise exception 'Wait for someone else after 5 messages'; end if; return new; end; $$;
create trigger guard_channel_message before insert on public.messages for each row execute function public.guard_chat_message(); create trigger guard_dm_message before insert on public.dm_messages for each row execute function public.guard_chat_message();
create policy "read community ranks" on public.user_roles for select to authenticated using(true);
revoke insert,update,delete on public.suspensions from authenticated;
revoke update on public.applications from authenticated;
create or replace function public.validate_application() returns trigger language plpgsql set search_path=public as $$ begin if new.status<>'pending' then raise exception 'Applications must be pending'; end if; if new.link !~ '^https://' then raise exception 'Use an https account link'; end if; if new.kind='youtuber' and (new.followers<50 or new.views<10000) then raise exception 'YouTube requires 50 subscribers and 10000 views'; end if; if new.kind='tiktoker' and (new.followers<10 or new.likes<25) then raise exception 'TikTok requires 10 followers and 25 likes'; end if; return new; end; $$;
create trigger validate_rank_application before insert on public.applications for each row execute function public.validate_application();
create or replace function public.notify_rank_application() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.notifications(user_id,kind,title,body) select user_id,'application','New rank application',new.kind||' application is awaiting review' from public.user_roles where role='owner'; return new; end; $$;
create trigger notify_rank_request after insert on public.applications for each row execute function public.notify_rank_application();
create or replace function public.guard_suspension() returns trigger language plpgsql set search_path=public as $$ begin if new.until_at>now()+interval '1 month' then raise exception 'Suspensions cannot exceed one month'; end if; return new; end; $$;
create trigger limit_suspension before insert or update on public.suspensions for each row execute function public.guard_suspension();
create or replace function public.award_streamer() returns trigger language plpgsql security definer set search_path=public as $$ begin if old.is_live and not new.is_live and (select count(*) from public.livestreams where host_id=new.host_id and not is_live)>=5 then insert into public.user_roles(user_id,role) values(new.host_id,'streamer') on conflict(user_id,role) do nothing; end if; return new; end; $$;
create trigger award_streamer_rank after update on public.livestreams for each row execute function public.award_streamer();
drop policy "frycord media read" on storage.objects; drop policy "frycord media insert" on storage.objects; drop policy "frycord media update" on storage.objects;
create policy "frycord authenticated media read" on storage.objects for select to authenticated using(bucket_id in ('chat-media','backgrounds','avatars'));
create policy "frycord owned media insert" on storage.objects for insert to authenticated with check(bucket_id in ('chat-media','backgrounds','avatars') and (storage.foldername(name))[1]=auth.uid()::text);
create policy "frycord owned media delete" on storage.objects for delete to authenticated using(bucket_id in ('chat-media','backgrounds','avatars') and owner_id=auth.uid()::text);